/// 弹幕服务（App 端：发送 / 视频弹幕拉取；拉取对游客开放）
class DanmakuServiceClient {
  final ClientTransport _transport;

  DanmakuServiceClient(this._transport);

  /// 发送弹幕（需登录；敏感词命中拒绝；sysconf 开关关闭拒绝）
  Future<DanmakuServiceV1Danmaku> sendDanmaku(DanmakuServiceV1SendDanmakuRequest request, {Map<String, String>? headers}) async {
    if (request.videoId == null) {
      throw ArgumentError('missing required field request.video_id');
    }
    final path = '/app/v1/videos/${request.videoId}/danmaku';
    final bodyMap = request.toJson();
    bodyMap.remove('videoId');
    final body = jsonEncode(bodyMap);
