/// 互动服务（App 端：点赞 / 收藏 / 关注 / 评论）
class InteractionServiceClient {
  final ClientTransport _transport;

  InteractionServiceClient(this._transport);

  /// 点赞（视频或评论）
  Future<InteractionServiceV1LikeResponse> like(InteractionServiceV1LikeRequest request, {Map<String, String>? headers}) async {
    final path = '/app/v1/likes';
    final body = jsonEncode(request.toJson());
    final result = await _transport.unary(path, 'POST', body, TransportMeta(
      service: 'InteractionService',
      method: 'Like',
    ), headers: headers);
    return InteractionServiceV1LikeResponse.fromJson(result as Map<String, dynamic>);
  }

  /// 取消点赞
  Future<InteractionServiceV1LikeResponse> unlike(InteractionServiceV1LikeRequest request, {Map<String, String>? headers}) async {
    if (request.targetType == null) {
      throw ArgumentError('missing required field request.target_type');
    }
    if (request.targetId == null) {
      throw ArgumentError('missing required field request.target_id');
    }
    final path = '/app/v1/likes/${request.targetType}/${request.targetId}';
    final result = await _transport.unary(path, 'DELETE', null, TransportMeta(
      service: 'InteractionService',
      method: 'Unlike',
    ), headers: headers);
    return InteractionServiceV1LikeResponse.fromJson(result as Map<String, dynamic>);
  }

  /// 收藏视频
  Future<InteractionServiceV1CollectResponse> collect(InteractionServiceV1CollectRequest request, {Map<String, String>? headers}) async {
    if (request.videoId == null) {
      throw ArgumentError('missing required field request.video_id');
    }
    final path = '/app/v1/videos/${request.videoId}/collect';
    final bodyMap = request.toJson();
    bodyMap.remove('videoId');
    final body = jsonEncode(bodyMap);
    final result = await _transport.unary(path, 'POST', body, TransportMeta(
      service: 'InteractionService',
      method: 'Collect',
    ), headers: headers);
    return InteractionServiceV1CollectResponse.fromJson(result as Map<String, dynamic>);
  }

  /// 取消收藏
  Future<InteractionServiceV1CollectResponse> uncollect(InteractionServiceV1CollectRequest request, {Map<String, String>? headers}) async {
    if (request.videoId == null) {
      throw ArgumentError('missing required field request.video_id');
    }
    final path = '/app/v1/videos/${request.videoId}/collect';
    final result = await _transport.unary(path, 'DELETE', null, TransportMeta(
      service: 'InteractionService',
      method: 'Uncollect',
    ), headers: headers);
    return InteractionServiceV1CollectResponse.fromJson(result as Map<String, dynamic>);
