/// 评论服务（App 端底部弹窗）
class CommentServiceClient {
  final ClientTransport _transport;

  CommentServiceClient(this._transport);

  /// 发表评论
  Future<InteractionServiceV1Comment> createComment(InteractionServiceV1CreateCommentRequest request, {Map<String, String>? headers}) async {
    if (request.videoId == null) {
      throw ArgumentError('missing required field request.video_id');
    }
    final path = '/app/v1/videos/${request.videoId}/comments';
    final bodyMap = request.toJson();
    bodyMap.remove('videoId');
    final body = jsonEncode(bodyMap);
    final result = await _transport.unary(path, 'POST', body, TransportMeta(
      service: 'CommentService',
      method: 'CreateComment',
    ), headers: headers);
    return InteractionServiceV1Comment.fromJson(result as Map<String, dynamic>);
  }

  /// 删除自己的评论
  Future<Map<String, dynamic>> deleteComment(InteractionServiceV1DeleteCommentRequest request, {Map<String, String>? headers}) async {
    if (request.id == null) {
      throw ArgumentError('missing required field request.id');
    }
    final path = '/app/v1/comments/${request.id}';
    final result = await _transport.unary(path, 'DELETE', null, TransportMeta(
      service: 'CommentService',
      method: 'DeleteComment',
    ), headers: headers);
    return result as Map<String, dynamic>;
  }

  /// 视频评论列表（分页）
  Future<InteractionServiceV1ListCommentResponse> listComment(InteractionServiceV1ListCommentRequest request, {Map<String, String>? headers}) async {
    if (request.videoId == null) {
      throw ArgumentError('missing required field request.video_id');
    }
    final path = '/app/v1/videos/${request.videoId}/comments';
    final queryParams = <String>[];
    if (request.pageNum != null) {
      queryParams.add('pageNum=${Uri.encodeComponent(request.pageNum!.toString())}');
    }
    if (request.pageSize != null) {
      queryParams.add('pageSize=${Uri.encodeComponent(request.pageSize!.toString())}');
    }
    if (request.sort != null) {
      queryParams.add('sort=${Uri.encodeComponent(request.sort!.toString())}');
    }
    var uri = path;
    if (queryParams.isNotEmpty) {
      uri += '?${queryParams.join("&")}';
    }
    final result = await _transport.unary(uri, 'GET', null, TransportMeta(
      service: 'CommentService',
      method: 'ListComment',
    ), headers: headers);
    return InteractionServiceV1ListCommentResponse.fromJson(result as Map<String, dynamic>);
  }

  /// 评论的回复列表（楼中楼）
  Future<InteractionServiceV1ListCommentResponse> listReply(InteractionServiceV1ListReplyRequest request, {Map<String, String>? headers}) async {
    if (request.commentId == null) {
      throw ArgumentError('missing required field request.comment_id');
    }
    final path = '/app/v1/comments/${request.commentId}/replies';
    final queryParams = <String>[];
    if (request.pageNum != null) {
      queryParams.add('pageNum=${Uri.encodeComponent(request.pageNum!.toString())}');
    }
    if (request.pageSize != null) {
      queryParams.add('pageSize=${Uri.encodeComponent(request.pageSize!.toString())}');
    }
    var uri = path;
    if (queryParams.isNotEmpty) {
      uri += '?${queryParams.join("&")}';
    }
    final result = await _transport.unary(uri, 'GET', null, TransportMeta(
      service: 'CommentService',
      method: 'ListReply',
    ), headers: headers);
    return InteractionServiceV1ListCommentResponse.fromJson(result as Map<String, dynamic>);
  }

  /// 置顶/取消置顶评论（视频作者本人）
  Future<InteractionServiceV1Comment> pinComment(InteractionServiceV1PinCommentRequest request, {Map<String, String>? headers}) async {
    if (request.id == null) {
      throw ArgumentError('missing required field request.id');
    }
    final path = '/app/v1/comments/${request.id}/pin';
    final bodyMap = request.toJson();
    bodyMap.remove('id');
    final body = jsonEncode(bodyMap);
    final result = await _transport.unary(path, 'PUT', body, TransportMeta(
      service: 'CommentService',
      method: 'PinComment',
    ), headers: headers);
    return InteractionServiceV1Comment.fromJson(result as Map<String, dynamic>);
  }
}

