/// 剧集服务（App 端：建剧 / 编辑 / 选集浏览；详情与列表对游客开放）
class SeriesServiceClient {
  final ClientTransport _transport;

  SeriesServiceClient(this._transport);

  /// 创建剧集（需登录）
  Future<SeriesServiceV1Series> createSeries(SeriesServiceV1CreateSeriesRequest request, {Map<String, String>? headers}) async {
    final path = '/app/v1/series';
    final body = jsonEncode(request.toJson());
    final result = await _transport.unary(path, 'POST', body, TransportMeta(
      service: 'SeriesService',
      method: 'CreateSeries',
    ), headers: headers);
    return SeriesServiceV1Series.fromJson(result as Map<String, dynamic>);
  }

  /// 剧集详情（剧信息 + 选集；游客仅见已发布集）
  Future<SeriesServiceV1SeriesDetail> getSeries(SeriesServiceV1GetSeriesRequest request, {Map<String, String>? headers}) async {
    if (request.id == null) {
      throw ArgumentError('missing required field request.id');
    }
    final path = '/app/v1/series/${request.id}';
    final result = await _transport.unary(path, 'GET', null, TransportMeta(
      service: 'SeriesService',
      method: 'GetSeries',
    ), headers: headers);
    return SeriesServiceV1SeriesDetail.fromJson(result as Map<String, dynamic>);
  }

  /// 编辑自己的剧集（标题 / 简介 / 封面）
  Future<SeriesServiceV1Series> updateSeries(SeriesServiceV1UpdateSeriesRequest request, {Map<String, String>? headers}) async {
    if (request.id == null) {
      throw ArgumentError('missing required field request.id');
    }
    final path = '/app/v1/series/${request.id}';
    final bodyMap = request.toJson();
    bodyMap.remove('id');
    final body = jsonEncode(bodyMap);
    final result = await _transport.unary(path, 'PUT', body, TransportMeta(
      service: 'SeriesService',
      method: 'UpdateSeries',
    ), headers: headers);
    return SeriesServiceV1Series.fromJson(result as Map<String, dynamic>);
  }

  /// 删除自己的剧集（剧内视频解挂不删除）
