/// 用户主页服务（App 端，shortplay 业务）
class UserServiceClient {
  final ClientTransport _transport;

  UserServiceClient(this._transport);

  /// 用户主页（本人 / 他人通用：资料；游客可访问）
  Future<UserDetail> getUser(GetAppUserRequest request, {Map<String, String>? headers}) async {
    if (request.id == null) {
      throw ArgumentError('missing required field request.id');
    }
    final path = '/app/v1/users/${request.id}';
    final result = await _transport.unary(path, 'GET', null, TransportMeta(
      service: 'UserService',
      method: 'GetUser',
    ), headers: headers);
    return UserDetail.fromJson(result as Map<String, dynamic>);
  }

  /// 用户统计（粉丝 / 关注 / 作品 / 获赞；游客可访问）
  Future<IdentityServiceV1UserStats> getUserStats(IdentityServiceV1GetUserStatsRequest request, {Map<String, String>? headers}) async {
    if (request.userId == null) {
      throw ArgumentError('missing required field request.user_id');
    }
    final path = '/app/v1/users/${request.userId}/stats';
    final result = await _transport.unary(path, 'GET', null, TransportMeta(
      service: 'UserService',
      method: 'GetUserStats',
    ), headers: headers);
    return IdentityServiceV1UserStats.fromJson(result as Map<String, dynamic>);
  }

  /// 编辑我的资料（id 取令牌）
  Future<UserDetail> updateProfile(UpdateProfileRequest request, {Map<String, String>? headers}) async {
    final path = '/app/v1/profile';
    final body = jsonEncode(request.toJson());
    final result = await _transport.unary(path, 'PUT', body, TransportMeta(
      service: 'UserService',
      method: 'UpdateProfile',
    ), headers: headers);
    return UserDetail.fromJson(result as Map<String, dynamic>);
  }

  /// 用户作品列表（主页「作品」Tab；本人可见全部状态，他人仅已发布）
  Future<VideoServiceV1ListVideoResponse> listUserVideos(ListUserVideosRequest request, {Map<String, String>? headers}) async {
    if (request.userId == null) {
      throw ArgumentError('missing required field request.user_id');
    }
    final path = '/app/v1/users/${request.userId}/videos';
    final queryParams = <String>[];
    if (request.pageNum != null) {
      queryParams.add('pageNum=${Uri.encodeComponent(request.pageNum!.toString())}');
    }
    if (request.pageSize != null) {
      queryParams.add('pageSize=${Uri.encodeComponent(request.pageSize!.toString())}');
    }
    var uri = path;
    if (queryParams.isNotEmpty) {
      uri += '?${queryParams.join("&")}';
    }
    final result = await _transport.unary(uri, 'GET', null, TransportMeta(
      service: 'UserService',
      method: 'ListUserVideos',
    ), headers: headers);
    return VideoServiceV1ListVideoResponse.fromJson(result as Map<String, dynamic>);
  }
}

